#!/usr/bin/env node
// Build lande, the language detector Harmony uses, for Apollo and the shared alias editor:
//
//   // <ST-LANDE> …generated, do not edit… // </ST-LANDE>
//
// lande is pinned in package.json; rerun only to change its version.
// Run:  pnpm vendor:lande   (in userscripts/apollo_editor)

import { build } from 'esbuild';
import { readFileSync, writeFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const HERE = dirname(fileURLToPath(import.meta.url));
const version = JSON.parse(readFileSync(resolve(HERE, '..', 'node_modules', 'lande', 'package.json'), 'utf8')).version;
const license = readFileSync(resolve(HERE, '..', 'node_modules', 'lande', 'license'), 'utf8').replace(/\r\n/g, '\n').trim();

const out = await build({
  stdin: { contents: "import lande from 'lande'; export default lande;", resolveDir: HERE, loader: 'js' },
  bundle: true, minify: true, format: 'iife', globalName: '__lande', target: 'es2019', write: false, legalComments: 'none',
});
const code = out.outputFiles[0].text.trim();

writeFileSync(resolve(HERE, '../../../dev/aliases/lande-vendor.js'), `// lande ${version} (MIT), generated by userscripts/apollo_editor/dev/build-lande.mjs.\n/*\n${license}\n*/\n// eslint-disable-next-line\nconst landeLoad = () => { ${code} return __lande.default; };\n`);
execFileSync(process.execPath, [resolve(HERE, '../../../dev/aliases/sync-aliases.mjs')], { stdio: 'inherit' });
console.log(`lande ${version}: ${Math.round(code.length / 1024)} KB shared with the alias editors`);
